<p class="eyebrow">Withdrawal request</p><h1><?= e($withdrawal['reference']) ?></h1><section class="card"><dl class="detail-list"><dt>Status</dt><dd><?= e($withdrawal['status']) ?></dd><dt>Requested</dt><dd><?= money((int)$withdrawal['requested_amount_minor']) ?></dd><dt>Fee</dt><dd><?= money((int)$withdrawal['fee_minor']) ?></dd><dt>Expected payout</dt><dd><?= money((int)$withdrawal['payout_amount_minor']) ?></dd><?php if($withdrawal['rejection_reason']): ?><dt>Why this withdrawal was rejected</dt><dd><?= e($withdrawal['rejection_reason']) ?></dd><?php endif; ?><?php if($withdrawal['payout_reference']): ?><dt>Payout reference</dt><dd><?= e($withdrawal['payout_reference']) ?></dd><?php endif; ?></dl><?php if($withdrawal['status']==='PENDING'): ?><form method="post" action="<?= e(route('dashboard.withdraw.cancel',['withdrawal'=>$withdrawal['reference']])) ?>"><?= app('csrf')->input() ?><button class="button button-secondary">Cancel withdrawal</button></form><?php endif; ?></section><section class="card"><h2>Destination details</h2><?php foreach($values as $value): ?><p><strong><?= e($value['field_label']) ?>:</strong> <?= e($value['value_text']) ?></p><?php endforeach; ?></section>
